/* Patient-linked follow-up: local rehearsal and server-enforced shared episodes. */
(()=>{
const initialEpisodes=state.dynamicEpisodes||{},initialProtocols=state.dynamicProtocols||{versions:[]};
Object.defineProperty(state,'dynamicEpisodes',{value:initialEpisodes,writable:true,configurable:true,enumerable:false});Object.defineProperty(state,'dynamicProtocols',{value:initialProtocols,writable:true,configurable:true,enumerable:false});state.dynamicCursors??={};
let database=null,storeReady=false,saveChain=Promise.resolve();const savedTokens=new Map();
async function openStore(){try{database=await new Promise((resolve,reject)=>{const request=indexedDB.open('fn-dynamic-followup-v1',1);request.onupgradeneeded=()=>request.result.createObjectStore('records',{keyPath:'id'});request.onsuccess=()=>resolve(request.result);request.onerror=()=>reject(request.error)});const records=await new Promise((resolve,reject)=>{const tx=database.transaction('records','readonly'),r=tx.objectStore('records').getAll();r.onsuccess=()=>resolve(r.result);r.onerror=()=>reject(r.error)});for(const r of records){if(r.id==='__protocols__')state.dynamicProtocols=r.value;else{const existing=state.dynamicEpisodes[r.id];if(!existing||r.value.events.length>=existing.events.length)state.dynamicEpisodes[r.id]=r.value}}storeReady=true;for(const d of Object.values(state.dynamicEpisodes))updateRegistry(d);render()}catch(e){storeReady=true;error='Persistent follow-up storage unavailable. Keep an export or use shared staff mode.';render()}}

let tab='Cases',patientId='',examples=[],validation=null,protocolId='',shared=null,loading=false,error='',role='admin',group='All patients',seenResults=new Set();
const labels={sbp:'Systolic BP',temp:'Temperature',anc:'ANC',crcl:'Verified CrCl',rr:'Respiratory rate',spo2:'SpO₂',newHypoxia:'New hypoxia',confusion:'Confusion',renalState:'Renal trajectory',allergy:'Allergy phenotype',allergyDrug:'Allergy drug category',resistance:'Resistance mechanism',pneumonia:'Pneumonia',priorAntibiotic:'Already on antibiotic',burden:'Symptom burden'};
const ratio=x=>x.percent===null?'Not available':x.percent+'% ('+x.numerator+'/'+x.denominator+')',when=x=>x?fmt(x):'Not recorded';
const actor=()=>({id:shared?.session?.userId||'LOCAL-SELF-ATTESTED',role:shared?shared.data.membership.role:role});
const can=r=>['admin',r].includes(actor().role);
function persist(){try{localStorage.setItem('fn-demo-v1',JSON.stringify(state))}catch{error='Device registry storage unavailable; export or use shared mode.'}if(!storeReady||!database)return;const changed=[];for(const [pid,d]of Object.entries(state.dynamicEpisodes)){const token=d.revision+':'+d.events.length;if(savedTokens.get(pid)!==token){changed.push({id:pid,value:structuredClone(d)});savedTokens.set(pid,token)}}const protocolToken=JSON.stringify(state.dynamicProtocols);if(savedTokens.get('__protocols__')!==protocolToken){changed.push({id:'__protocols__',value:structuredClone(state.dynamicProtocols)});savedTokens.set('__protocols__',protocolToken)}if(!changed.length)return;saveChain=saveChain.then(()=>new Promise((resolve,reject)=>{const tx=database.transaction('records','readwrite');for(const row of changed)tx.objectStore('records').put(row);tx.oncomplete=resolve;tx.onerror=()=>reject(tx.error)})).catch(e=>{error='Follow-up could not be saved; export your record before closing.';savedTokens.clear()})}

function patient(){return patients.find(p=>id(p)===patientId)}
function visit(){return shared?.data.visits.find(v=>v.id===shared.visitId)}
function episode(){return shared?visit()?.snapshot.dynamic:state.dynamicEpisodes[patientId]}
function localProtocols(){return shared?shared.data.protocols.find(p=>p.id===protocolId)?.snapshot.protocol||{versions:[]}:state.dynamicProtocols}
function activeProtocol(){return localProtocols().versions.filter(p=>p.status==='active').at(-1)||FNDynamic.defaultProtocol}
function updateRegistry(d){if(!d)return;const p=patients.find(p=>id(p)===d.patientId);if(!p)return;if(fnA2A.dynamicInput(d.patientId,d.input))return;const overlay=FNActionRegistry.patient({id:'DYNAMIC-'+d.patientId,patientId:d.patientId,displayName:patientName(p),title:'Follow-up assessment',input:d.input,simulationStartedAt:d.triageAt},d.input);state.assessments[d.patientId]={...p,...overlay,Diagnosis:p.Diagnosis};}
function initializeLocal(pid,save=true){const p=patients.find(p=>id(p)===pid);if(!p)return null;if(!state.dynamicEpisodes[pid]){const input=FNDynamic.fromPatient(p),known=!!p._savedAt;state.dynamicEpisodes[pid]=FNDynamic.initialize({patientId:pid,label:patientName(p),input,triageAt:p._savedAt||new Date().toISOString(),triageKnown:known,protocol:activeProtocol(),mode:'recorded'},Date.now());if(save)persist()}return state.dynamicEpisodes[pid]}
function setTab(v){tab=v;error='';render()}
function renderPage(){const d=episode(),a=actor();return header('Dynamic reassessment','Follow new data, accountable actions, test results and the decision that follows.',`<button class="btn" onclick="fnDyn.export()">Export follow-up record</button>`)+`<div class="dyn-banner"><b>${shared?'Shared staff workflow · server-enforced roles':'Device-local rehearsal · role selection is self-attested'}</b><p>All patients are synthetic. Changes create reviewable proposals; previous accepted plans and completed actions remain visible. No live LIS/EHR feed, automatic prescribing or background emergency dispatch is connected.</p></div><div class="dyn-tabs">${['Cases','Actions & tests','Local protocol','Measured use','Validation lab'].map(v=>`<button class="${v===tab?'active':''}" onclick="fnDyn.tab('${v}')">${v}</button>`).join('')}</div>${error?`<div class="notice" role="alert">${esc(error)}</div>`:''}<section class="panel dyn-controls"><div class="dyn-fields"><label>Patient cohort<select onchange="fnDyn.group(this.value)">${['All patients','10 entered examples','20 teaching scenarios','Existing workbook / walkthroughs'].map(v=>`<option ${v===group?'selected':''}>${v}</option>`).join('')}</select></label><label>Patient<select id="dyn-patient" onchange="fnDyn.select(this.value)"><option value="">Choose a patient</option>${patients.filter(p=>group==='All patients'||group==='10 entered examples'&&examples.some(e=>'SIM-'+e.enteredId===id(p))||group==='20 teaching scenarios'&&/^SIM-A2A-/.test(id(p))||group==='Existing workbook / walkthroughs'&&/^(FN-|WALK-)/.test(id(p))).map(p=>`<option value="${id(p)}" ${id(p)===patientId?'selected':''}>${esc(patientName(p))} · ${id(p)}</option>`).join('')}</select></label>${!shared?`<label>Rehearsal role<select onchange="fnDyn.role(this.value)">${['admin','physician','pharmacist','nurse'].map(v=>`<option ${v===role?'selected':''}>${v}</option>`).join('')}</select></label>`:`<p>Signed-in role: <b>${esc(a.role)}</b> · ${esc(shared.data.membership.label)}</p>`}</div><div class="actions"><button class="btn" onclick="fnDyn.connect()" ${loading?'disabled':''}>${loading?'Loading…':'Load shared workspace'}</button>${shared?'<button class="btn" onclick="fnDyn.local()">Return to local rehearsal</button>':''}${patientId&&!shared?'<button class="btn primary" onclick="fnDyn.enroll()">Open / enroll patient follow-up</button>':''}${shared?`<label>Shared visit<select onchange="fnDyn.sharedVisit(this.value)"><option value="">Choose visit</option>${shared.data.visits.map(v=>`<option value="${v.id}" ${v.id===shared.visitId?'selected':''}>${esc(v.case_code)} · v${v.revision}${v.snapshot.dynamic?' · tracked':''}</option>`).join('')}</select></label>${visit()&&!d?'<button class="btn primary" onclick="fnDyn.enrollShared()">Enroll this shared visit</button>':''}`:''}</div>${!shared?'<p class="mini">Local role controls are a demonstration. Shared mode uses actual approved staff membership and optimistic revision checks.</p>':'<p class="mini">New shared visits are created from the existing patient/team or entered-assessment workflow. Refresh before an action; newer revisions cannot be overwritten.</p>'}</section>${tab==='Local protocol'?protocolView():tab==='Measured use'?metricsView():tab==='Validation lab'?validationView():!d?emptyView():tab==='Actions & tests'?tasksView(d)+testsView(d):caseView(d)}`}
function emptyView(){return `<section class="panel"><h2>Patient-linked follow-up</h2><p>All registry patients can be enrolled: imported workbook cases, the 20 teaching scenarios and newly entered assessments. Unknown source fields remain unknown.</p><button class="btn primary" onclick="fnDyn.examples()">Open the 10 entered examples</button><div class="dyn-example-grid">${examples.map(e=>`<button onclick="fnDyn.example('${e.id}')"><small>${e.id} · ${esc(e.name)}</small><b>${esc(e.title)}</b><span>${esc(e.expectedInitial)}</span></button>`).join('')}</div></section>`}
function caseView(d){const ex=examples.find(e=>'SIM-'+e.enteredId===d.patientId),cursor=state.dynamicCursors[d.patientId]||0,currentValid=FNDynamic.currentPlan(d);return `<div class="dyn-stats"><div><small>Current suggested track</small><b>${esc(d.current.risk)}</b><span>MASCC ${d.current.score??'incomplete'} · input revision ${d.revision}</span></div><div><small>Review queue</small><b>${d.alerts.filter(a=>!a.review).length} unreviewed</b><span>Plan ${currentValid?'reviewed for current revision':'requires current-revision review'}</span></div><div><small>Applied local protocol</small><b>${esc(d.protocol.name)} v${d.protocol.version}</b><span>${esc(d.protocol.status)} · ${d.triageKnown?'Triage '+when(d.triageAt):'Source triage unknown; first-hour timing unavailable'}</span></div></div><section class="panel"><div class="sectiontitle"><div><h2>${esc(d.label)} · follow-up</h2><p>${esc(d.patientId)} · previous actions are retained when inputs change.</p></div><div class="actions"><button class="btn primary" onclick="fnDyn.observation()">Record new observation</button><button class="btn" onclick="fnDyn.report()">Receive a lab / culture report</button></div></div>${ex&&!shared?`<div class="notice"><b>Entered example ${ex.id}</b> · ${esc(ex.title)}<p>Initial expected pathway: ${esc(ex.expectedInitial)}. New Assessment opens the prefilled example; future example events are released one stage at a time.</p><div class="actions"><button class="btn" onclick="fnDyn.entered('${ex.id}')">Open prefilled New Assessment</button><button class="btn primary" onclick="fnDyn.next('${ex.id}')" ${cursor>=ex.events.length?'disabled':''}>${cursor>=ex.events.length?'All example events released':'Release next fictional event ('+(cursor+1)+'/'+ex.events.length+')'}</button></div></div>`:''}${ex?`<details><summary>Entered example baseline laboratory values · fictional</summary><div class="scroll"><table><thead><tr><th>Test</th><th>Value</th><th>Available after presentation</th></tr></thead><tbody>${ex.labs.filter(l=>l.at<=(cursor?ex.events[cursor-1].at:0)).map(l=>`<tr><td>${esc(l.name)}</td><td>${l.value??'Not available'} ${esc(l.unit)}</td><td>+${l.at} min</td></tr>`).join('')}</tbody></table></div><p>No future culture or AST is used before its release stage. These are source fixtures, not certified live laboratory events.</p></details>`:''}<p>Initial assessment: <b>${esc(d.initial.risk)}</b> · Current numeric FN pattern: <b>${esc(d.current.fn)}</b>. Prior FN history, current care and clinical judgment remain relevant even after a temperature improves.</p><p>${esc(d.current.reasons.join('; ')||'No additional recorded override. Missing information is not evidence of safety.')}</p>${d.current.alerts.map(a=>`<p class="dyn-note">${esc(a)}</p>`).join('')}<details><summary>Current reference medicines (unsigned)</summary>${d.current.meds.map(m=>`<p><b>${esc(m.name)}</b>: ${esc(m.first)} · ${esc(m.maintenance)}${m.blocked?' · individualized review required':''}</p>`).join('')||'<p>No new numeric initial-dose reference. Review ongoing treatment and current safety gaps.</p>'}</details></section><section class="panel dyn-section"><h2>Changes → review → decision</h2>${d.alerts.slice().reverse().map(a=>`<article class="dyn-change"><div class="sectiontitle"><b>${esc(a.reason)}</b><span class="pill ${a.review?'':'amber'}">${esc(a.status)}</span></div><div class="dyn-compare"><p><small>Before</small><b>${esc(a.before.risk)}</b>MASCC ${a.before.score??'unknown'} · ${esc(a.before.meds.map(m=>m.name).join(', ')||'No new initial-dose reference')}</p><p><small>After</small><b>${esc(a.after.risk)}</b>MASCC ${a.after.score??'unknown'} · ${esc(a.after.meds.map(m=>m.name).join(', ')||'No new initial-dose reference')}</p></div><p class="mini">Observed ${when(a.observedAt)} · available ${when(a.availableAt)} · received ${when(a.receivedAt)} · detected ${when(a.detectedAt)} · review due ${when(a.dueAt)}</p><p>${a.review?'Reviewed '+when(a.review.at)+' · '+esc(a.review.note):'Awaiting clinician/pharmacy acknowledgment'}</p><p>${a.decision?'Decision: '+esc(a.decision.value)+' · '+esc(a.decision.note):'No decision recorded. Acknowledgment alone does not close the decision.'}</p><div class="actions">${!a.review&&can('physician')||!a.review&&can('pharmacist')?`<button class="btn" onclick="fnDyn.alert('${a.id}',false)">Review this change</button>`:''}${a.review&&can('physician')&&!a.decision?`<button class="btn primary" onclick="fnDyn.alert('${a.id}',true)">Record clinical decision</button>`:''}</div></article>`).join('')||'<p>No changed data recorded yet. Add a new observation or release a teaching event.</p>'}</section>${planView(d)}${auditView(d)}`}
function planView(d){return `<section class="panel dyn-section"><h2>Physician → pharmacy → dose documentation</h2><p><b>Last accepted plan:</b> ${d.acceptedPlan?esc(d.acceptedPlan.text):'None recorded'}</p><p class="mini">${d.acceptedPlan?'Accepted for input revision '+d.acceptedPlan.inputRevision+', protocol v'+d.acceptedPlan.protocolVersion+'. '+(FNDynamic.currentPlan(d)?'Current-revision approval present.':'Retained as prior plan; new revision needs approval.'):'No automatic approval.'}</p>${d.proposal?`<details open><summary>Current physician proposal</summary><p style="white-space:pre-wrap">${esc(d.proposal.text)}</p><p>Revision ${d.proposal.inputRevision} · pharmacy ${esc(d.proposal.pharmacy?.decision||'pending')}</p></details>`:''}<div class="actions">${can('physician')?'<button class="btn" onclick="fnDyn.plan()">Propose / revise plan</button>':''}${can('pharmacist')&&d.proposal?'<button class="btn" onclick="fnDyn.pharmacy()">Pharmacy review</button>':''}${can('nurse')?'<button class="btn primary" onclick="fnDyn.dose()">Document a reviewed dose</button>':''}<button class="btn" onclick="fnDyn.tab('Actions & tests')">Assigned actions & tests</button></div><p class="mini">Recording an infusion start is distinct from completing the infusion. This application never administers or transmits a medicine order.</p></section>`}
function tasksView(d){return `<section class="panel"><div class="sectiontitle"><h2>Assigned actions to documented execution</h2>${can('physician')?'<button class="btn" onclick="fnDyn.addTask()">Add follow-up action</button>':''}</div><div class="scroll"><table><thead><tr><th>Action / owner</th><th>Due / status</th><th>Evidence</th><th>Next action</th></tr></thead><tbody>${d.tasks.map(t=>`<tr><td><b>${esc(t.title)}</b><br>${esc(t.ownerRole)} · ${esc(t.ownerLabel)}</td><td>${when(t.dueAt)}<br><span class="pill ${t.status==='completed'?'':'amber'}">${esc(t.status)}</span></td><td>${t.completedAt?'Actual '+when(t.completedAt)+' · '+esc(t.evidence):esc(t.deferReason||t.cancelReason||'Not documented')}</td><td>${!['completed','cancelled'].includes(t.status)?`<button class="btn" onclick="fnDyn.task('${t.id}')">Manage action</button>`:'Retained record'}</td></tr>`).join('')}</tbody></table></div><p class="mini">Completion requires an explicit actual time and evidence note. Deferred actions remain in the completion denominator. Cancelled actions are reported separately.</p></section>`}
function testsView(d){return `<section class="panel dyn-section"><div class="sectiontitle"><h2>Test order → specimen → result → decision</h2><div class="actions">${can('physician')?'<button class="btn" onclick="fnDyn.requestTest()">Request a test</button>':''}<button class="btn" onclick="fnDyn.report()">Receive report</button></div></div>${d.tests.map(t=>`<article class="dyn-test"><div class="sectiontitle"><h3>${esc(t.name)} · ${esc(t.id)}</h3><span class="pill">${esc(t.status)}</span></div><p>Responsible clinician: ${esc(t.ownerLabel)} · requested ${when(t.requestedAt)} · collected ${when(t.collectedAt)} · received ${when(t.receivedAt)}</p>${t.latest?`<p><b>${esc(t.latest.organism||(t.latest.value??'Result received'))}</b> ${esc(t.latest.unit)} · ${esc(t.latest.status)} · ${esc(t.latest.text)}</p><p>${Object.entries(t.latest.ast||{}).map(([k,v])=>esc(k)+': '+esc(v)).join(' · ')}</p><p>Current report: ${t.latest.ack?'acknowledged '+when(t.latest.ack.at):'awaiting acknowledgment'} · ${t.latest.decision?'decision '+esc(t.latest.decision.value)+' — '+esc(t.latest.decision.note):'decision pending'}</p>`:'<p>Results pending. Collection / receipt is not assumed when documentation is absent.</p>'}<div class="actions">${can('nurse')&&['requested','collected'].includes(t.status)?`<button class="btn" onclick="fnDyn.testStatus('${t.id}')">Document specimen status</button>`:''}${can('physician')?`<button class="btn" onclick="fnDyn.assignTest('${t.id}')">Assign responsible clinician</button>`:''}${t.latest&&!t.latest.ack&&(can('physician')||can('pharmacist'))?`<button class="btn" onclick="fnDyn.resultReview('${t.id}',false)">Acknowledge current result</button>`:''}${t.latest?.ack&&t.latest.code==='culture'&&can('physician')?`<button class="btn primary" onclick="fnDyn.resultReview('${t.id}',true)">Record culture-to-treatment decision</button>`:''}</div><details><summary>Report versions & amendments (${t.reports.length})</summary>${t.reports.map(r=>`<p>${when(r.availableAt)} · ${esc(r.status)} · ${esc(r.organism||(r.value??''))} · ${r.decision?'decision recorded for this version':'no decision'}${r.superseded?' · superseded':''}</p>`).join('')}</details></article>`).join('')||'<p>No test orders or result reports linked yet.</p>'}</section>`}
function protocolView(){const r=localProtocols();return `<section class="panel"><h2>Hospital local protocol · versioned governance</h2><p>Configure the local formulary, review timing, escalation team, scope and evidence. Existing reference-dose rules are retained; an unavailable drug is held for individual review rather than silently substituted.</p>${shared?`<label>Protocol record<select onchange="fnDyn.protocolRecord(this.value)"><option value="">Choose record</option>${shared.data.protocols.map(p=>`<option value="${p.id}" ${p.id===protocolId?'selected':''}>${esc(p.snapshot.protocol.versions.at(-1).name)} · record ${p.id.slice(0,8)}</option>`).join('')}</select></label>`:''}<div class="actions">${can('admin')?'<button class="btn primary" onclick="fnDyn.editProtocol()">Create / revise local protocol</button>':''}</div>${r.versions.slice().reverse().map(p=>`<article class="dyn-test"><h3>${esc(p.hospital)} · ${esc(p.name)} · v${p.version}</h3><span class="pill">${esc(p.status)}</span><p>${esc(p.ward)} · antibiotic target ${p.antibioticMinutes} min · change review target ${p.reviewMinutes} min · escalation ${esc(p.escalationTeam)}</p><p>Formulary: ${esc(p.allowedDrugs.join(', '))}</p><p>Evidence: ${esc(p.references)}</p><p>${esc(p.notes)}</p><p>Physician review ${p.approvals.physician?when(p.approvals.physician.at):'pending'} · Pharmacy review ${p.approvals.pharmacist?when(p.approvals.pharmacist.at):'pending'}</p><div class="actions">${p.version===r.versions.at(-1).version&&can('physician')?`<button class="btn" onclick="fnDyn.approveProtocol(${p.version},'physician')">Record physician protocol review</button>`:''}${p.version===r.versions.at(-1).version&&can('pharmacist')?`<button class="btn" onclick="fnDyn.approveProtocol(${p.version},'pharmacist')">Record pharmacy protocol review</button>`:''}${p.status==='active'&&episode()&&can('physician')?`<button class="btn primary" onclick="fnDyn.applyProtocol(${p.version})">Apply v${p.version} to selected episode</button>`:''}</div></article>`).join('')||'<p>No local protocol configured. Episodes use the clearly labelled draft reference until a reviewed local version is explicitly applied.</p>'}<p class="notice">“Active” records workflow review in this training application. It is not certification of institutional clinical validation. Administrator rehearsals show the administrator as the actual actor.</p></section>`}
function metricCards(m){return `<div class="dyn-stats"><div><small>Episodes / detected changes</small><b>${m.episodes} / ${m.changes}</b><span>${m.pendingReviews} pending reviews; ${m.overdueReviews} overdue</span></div><div><small>Receipt → detection, median</small><b>${m.receivedToDetectionSeconds===null?'No data':m.receivedToDetectionSeconds+' sec'}</b><span>Timestamp resolution; not a throughput benchmark</span></div><div><small>Detection → review, median</small><b>${m.detectionToReviewMinutes===null?'No data':m.detectionToReviewMinutes.toFixed(1)+' min'}</b><span>Reviewed changes only</span></div><div><small>Changes reviewed</small><b>${ratio(m.reviewRate)}</b></div><div><small>Required actions completed</small><b>${ratio(m.completionRate)}</b><span>${m.cancelledTasks} cancelled; ${m.deferredTasks} deferred</span></div><div><small>Completed actions on time</small><b>${ratio(m.onTimeCompletion)}</b><span>${m.overdueTasks} open overdue actions</span></div><div><small>Current reports acknowledged</small><b>${ratio(m.resultReviewRate)}</b></div><div><small>Current cultures with decisions</small><b>${ratio(m.cultureDecisionRate)}</b></div></div>`}
function metricsView(){const list=shared?shared.data.visits.map(v=>v.snapshot.dynamic).filter(Boolean):Object.values(state.dynamicEpisodes),m=FNDynamic.metrics(list.filter(d=>d.alerts.length||d.events.some(e=>!e.baseline&&e.by!=='LOCAL-RESULT-ADAPTER')),'recorded');return `<section class="panel"><h2>Recorded staff use on synthetic cases</h2><p>${shared?'Server-persisted staff workflow events.':'Device-local, self-attested training interactions.'} ${list.length} linked baseline episodes; only episodes with changed-data or documented staff interaction enter these use rates. Scripted runs are excluded. These are process measures, not proven clinical outcome improvements.</p></section>${metricCards(m)}<section class="panel"><h2>How the measures are calculated</h2><p>Detection: recorded detection time minus application receipt time. Review: first acknowledgment minus detection time. Completion: required, non-cancelled actions with an explicit completed status, actual time and evidence / all required non-cancelled actions. Culture decision: latest non-cancelled culture reports with a clinician decision / latest culture reports.</p><p>Missing timestamps stay unavailable; unreviewed changes and deferred tasks are not counted as completed. Old/amended reports remain in the audit but only the current report enters current-result rates. No pre/post comparison or patient outcome benefit is invented.</p><button class="btn" onclick="fnDyn.exportMetrics()">Export definitions & measured process data</button></section>`}
function validationView(){return `<section class="panel"><h2>10 entered examples · controlled simulation</h2><p>High-risk, low-risk and changing-pathway examples are linked to New Assessment and the patient registry. Expected classifications are checked independently at each released stage.</p><button class="btn primary" onclick="fnDyn.runValidation()">Run / recompute 10 scripted examples</button><button class="btn" onclick="fnDyn.exportValidation()">Export simulation evidence</button><p class="notice">Scripted staff roles, collection, review and administration times are invented teaching data. They never populate recorded-use measures or claim actual clinical benefit. The script deliberately leaves some actions pending, so completion is not assumed to be 100%.</p></section>${validation?`<div class="banner"><b>${validation.pass?'All expected pathway checks passed':'Review failed expectations'}</b> · ${validation.runs.length} cases · ${validation.summary.changes} detected changes</div>${metricCards(validation.summary)}<section class="panel"><h2>Case-level evidence</h2>${validation.runs.map(r=>`<details><summary>${r.exampleId} · ${esc(r.name)} · ${r.checks.every(c=>c.pass)?'pass':'review'}</summary><p>Initial: expected ${esc(r.initialExpected)} / actual ${esc(r.initialActual)}</p>${r.checks.map(c=>`<p>Stage ${c.stage+1}: expected ${esc(c.expected)} / actual ${esc(c.actual)} · ${c.pass?'pass':'FAIL'}</p>`).join('')}<p>Documented event count ${r.episode.events.length}; completed actions ${r.episode.tasks.filter(t=>t.status==='completed').length}/${r.episode.tasks.length}. Simulation only.</p></details>`).join('')}</section>`:'<p>Run the examples to calculate the simulated process evidence.</p>'}`}
function auditView(d){return `<section class="panel dyn-section"><details><summary>Observation, action and decision audit (${d.events.length})</summary>${d.events.slice().reverse().map(e=>`<p><b>${when(e.at)} · ${esc(e.action)}</b><br>${esc(e.by)} / ${esc(e.role)} · revision ${e.revision} · ${esc(e.note)}${e.stale?' · older observation retained without overwriting newer data':''}</p>`).join('')}</details></section>`}
async function refreshShared(){const session=await teamRequest('session');if(!session.workspaces.length)throw Error('No shared hospital workspace. Create or join one through Connected demo.');if(!session.workspaces.some(w=>w.id===teamWorkspaceId))teamWorkspaceId=session.workspaces[0].id;const data=await teamRequest('workspace');shared={session,data,visitId:shared?.visitId||'',};if(!data.protocols.some(p=>p.id===protocolId))protocolId=data.protocols[0]?.id||'';}
async function perform(op){error='';try{op.operationKey=op.operationKey||teamRequestId();if(shared){const v=visit();if(!v)throw Error('Choose a shared visit');await teamRequest('dynamic','POST',{id:v.id,revision:v.revision,operation:op});await refreshShared();const d=episode();if(d)updateRegistry(d)}else{const d=initializeLocal(patientId);if(!d)throw Error('Choose a patient');state.dynamicEpisodes[patientId]=FNDynamic.mutate(d,op,actor(),Date.now());updateRegistry(state.dynamicEpisodes[patientId]);persist()}closeDialog();render()}catch(e){error=e.message;const box=document.querySelector('#dyn-form-error');if(box)box.textContent=e.message;else render()}}
function dialog(title,fields,submit){openDialog(title,`<form id="dyn-form"><div class="dyn-fields">${fields}</div><label class="field">Rationale / evidence note<textarea name="note" required maxlength="800"></textarea></label><p id="dyn-form-error" role="alert"></p><div class="actions"><button class="btn primary" type="submit">Save documented action</button><button class="btn" type="button" onclick="closeDialog()">Cancel</button></div></form>`);document.querySelector('#dyn-form').onsubmit=e=>{e.preventDefault();submit(Object.fromEntries(new FormData(e.target)))}}
const field=(name,label,value='',type='text')=>`<label>${label}<input name="${name}" type="${type}" value="${esc(value)}" ${type==='text'?'maxlength="4000"':''}></label>`;
const choice=(name,label,values)=>`<label>${label}<select name="${name}">${values.map(v=>`<option value="${esc(Array.isArray(v)?v[0]:v)}">${esc(Array.isArray(v)?v[1]:v)}</option>`).join('')}</select></label>`;
window.fnDyn={policySuggestion(r,pid){const p=state.dynamicEpisodes[pid]?.protocol||activeProtocol();return {...r,localPolicy:{name:p.name,version:p.version,status:p.status},meds:r.meds.map(m=>({...m,blocked:m.blocked||!p.allowedDrugs.includes(m.code)})),alerts:[...r.alerts,...r.meds.filter(m=>!p.allowedDrugs.includes(m.code)).map(m=>'Local formulary excludes '+m.name+'; individualized prescriber/pharmacy selection required.')],antibioticClock:r.elapsedMinutes===null?r.antibioticClock:r.input.priorAntibiotic===true?r.antibioticClock:r.elapsedMinutes>p.antibioticMinutes?'Local antibiotic target elapsed — verify documented care':Math.ceil(p.antibioticMinutes-r.elapsedMinutes)+' min to local antibiotic target'}},pickExample(){openDialog('Load an entered assessment example',`<p>These are fictional prefilled assessments with expected pathways. Loading does not approve treatment or document completed care.</p><div class="dyn-example-grid">${examples.map(e=>`<button onclick="fnDyn.entered('${e.id}')"><small>${e.id} · ${esc(e.name)}</small><b>${esc(e.title)}</b><span>${esc(e.expectedInitial)}</span></button>`).join('')}</div>`)},tab:setTab,role(v){role=v;render()},group(v){group=v;render()},select(pid){patientId=pid;error='';if(pid&&!shared){initializeLocal(pid);scanResults(pid)}render()},open(pid){patientId=pid||patientId;if(patientId&&!shared){initializeLocal(patientId);scanResults(patientId)}go('Dynamic reassessment')},enroll(){if(patientId){initializeLocal(patientId);scanResults(patientId);render()}},examples(){group='10 entered examples';patientId='';tab='Cases';go('Dynamic reassessment')},example(id){const e=examples.find(e=>e.id===id);if(!e)return;shared=null;patientId='SIM-'+e.enteredId;group='10 entered examples';initializeLocal(patientId);tab='Cases';go('Dynamic reassessment')},entered(id){shared=null;closeDialog();const e=examples.find(e=>e.id===id),c=state.customActionCases.find(c=>c.id===e?.enteredId);if(c)fnIntake.edit({...c,input:state.dynamicEpisodes[c.patientId]?.input||c.input})},async next(id){const ex=examples.find(e=>e.id===id),i=state.dynamicCursors[patientId]||0,event=ex?.events[i];if(!event||shared)return;const d=episode();const anchor=Date.parse(ex.anchor),at=new Date(anchor+event.at*60000).toISOString();await perform({action:'observe',note:'Released fictional example event '+(i+1)+': '+event.label,event:{patch:event.patch,result:event.result||undefined,observedAt:at,availableAt:at,source:'Manual release of fictional example '+ex.id}});if(!error){state.dynamicCursors[patientId]=i+1;persist();render()}},async connect(){loading=true;error='';render();try{await refreshShared()}catch(e){error=e.message;shared=null}finally{loading=false;render()}},local(){shared=null;render()},sharedVisit(id){shared.visitId=id;const v=visit();patientId=v?.case_code||patientId;render()},async enrollShared(){const v=visit();if(!v)return;const p=patients.find(p=>id(p)===v.case_code);try{await teamRequest('dynamic','POST',{id:v.id,revision:v.revision,input:p?FNDynamic.fromPatient(p):undefined,operation:{action:'enroll',operationKey:teamRequestId(),label:p?patientName(p):v.case_code}});await refreshShared();render()}catch(e){error=e.message;render()}},observation(){dialog('New observation → reassessment',choice('key','Clinical field',Object.entries(labels).map(([k,v])=>[k,v]))+'<label>New value<input name="value" placeholder="Number, enum value, Yes / No / Unknown"></label>'+field('observedAt','Observed at',localInput(new Date().toISOString()),'datetime-local')+field('availableAt','Available at',localInput(new Date().toISOString()),'datetime-local')+field('source','Source / provenance','Operator-entered synthetic observation'),v=>{let value=v.value.trim();const k=v.key;if(FNAction.bools.includes(k))value=/^(yes|true)$/i.test(value)?true:/^(no|false)$/i.test(value)?false:null;else if(FNAction.ranges[k])value=value===''?null:Number(value);perform({action:'observe',note:v.note,event:{patch:{[k]:value},observedAt:new Date(v.observedAt).toISOString(),availableAt:new Date(v.availableAt).toISOString(),source:v.source}})});const select=document.querySelector('[name="key"]');select.onchange=()=>{const key=select.value,input=document.querySelector('[name="value"]');input.placeholder=FNAction.enums[key]?'Allowed: '+FNAction.enums[key].join(', '):FNAction.bools.includes(key)?'Yes / No / Unknown':'Numeric value; empty = unknown'};},report(){const d=episode();dialog('Receive a report — preserve collection uncertainty',field('testId','Test / accession ID',d?.tests[0]?.id||'culture-main')+choice('code','Report type',['culture','ANC','CrCl','Creatinine','Lactate','Galactomannan','WBC','Platelets','CRP'])+choice('status','Report status',['preliminary','final','corrected','cancelled'])+field('value','Numeric value or Positive / Negative / Pending')+field('unit','Reported unit')+field('organism','Organism (if reported)')+field('ast','Reported AST: agent:S, agent:R')+field('reportText','Report text / mechanism evidence')+field('observedAt','Observed at',localInput(new Date().toISOString()),'datetime-local')+field('availableAt','Available at',localInput(new Date().toISOString()),'datetime-local'),v=>{try{const ast={};if(v.ast.trim())for(const pair of v.ast.split(',')){const [drug,s]=pair.split(':').map(s=>s.trim());if(!drug||!s)throw Error('Use agent:S, agent:R');ast[drug]=s}const value=v.code==='culture'?v.value:v.value===''?null:Number(v.value),patch={};if(v.code==='ANC')patch.anc=value;if(v.code==='CrCl')patch.crcl=value;perform({action:'observe',note:v.note,event:{patch,observedAt:new Date(v.observedAt).toISOString(),availableAt:new Date(v.availableAt).toISOString(),source:'Operator-entered synthetic report',result:{testId:v.testId,accession:v.testId,code:v.code,status:v.status,value,unit:v.unit,organism:v.organism,ast,text:v.reportText}}})}catch(e){document.querySelector('#dyn-form-error').textContent=e.message}})},alert(id,decision){dialog(decision?'Decision after review':'Acknowledge changed data',decision?choice('decision','Decision',['retain','revise','escalate','defer']):'',v=>perform({action:decision?'decide_alert':'review_alert',alertId:id,decision:v.decision,note:v.note}))},plan(){const d=episode();dialog('Physician proposal for current revision',`<label>Reviewable plan<textarea name="plan" required maxlength="4000">${esc(d?.proposal?.text||['Current '+d?.current.risk,...(d?.current.meds||[]).map(m=>m.name+': '+m.first+' / '+m.maintenance)].join('\n'))}</textarea></label>`,v=>perform({action:'propose_plan',plan:v.plan,note:v.note}))},pharmacy(){dialog('Pharmacy review of physician proposal',choice('decision','Decision',['approve','changes']),v=>perform({action:'pharmacy_plan',decision:v.decision,note:v.note}))},dose(){dialog('Document actual synthetic dose — current plan required',field('regimen','Regimen actually documented')+field('actualAt','Actual administration / infusion start',localInput(new Date().toISOString()),'datetime-local'),v=>perform({action:'record_dose',regimen:v.regimen,actualAt:new Date(v.actualAt).toISOString(),note:v.note}))},task(id){const t=episode().tasks.find(t=>t.id===id);dialog('Manage action · '+t.title,choice('action','Action',['assign_task','approve_task','start_task','complete_task','defer_task','cancel_task'])+field('ownerLabel','Assigned operator label',t.ownerLabel)+field('actualAt','Actual completion time (when completing)',localInput(new Date().toISOString()),'datetime-local')+(t.code==='antibiotic'?field('regimen','Actual documented regimen'):''),v=>perform({action:v.action,taskId:id,ownerRole:t.ownerRole,ownerLabel:v.ownerLabel,actualAt:v.actualAt?new Date(v.actualAt).toISOString():undefined,regimen:v.regimen,note:v.note}))},addTask(){dialog('Add a clinician-directed follow-up task',field('title','Required follow-up')+choice('ownerRole','Responsible role',['physician','nurse','pharmacist'])+field('dueAt','Due time',localInput(new Date(Date.now()+15*60000).toISOString()),'datetime-local'),v=>perform({action:'add_task',title:v.title,ownerRole:v.ownerRole,dueAt:new Date(v.dueAt).toISOString(),note:v.note}))},requestTest(){dialog('Request a synthetic test',field('testId','Unique order / specimen ID')+field('name','Test name')+field('ownerLabel','Responsible clinician'),v=>perform({action:'request_test',testId:v.testId,name:v.name,ownerLabel:v.ownerLabel,note:v.note}))},testStatus(id){const t=episode().tests.find(t=>t.id===id);dialog('Document specimen status',`<p>Next status: ${t.status==='requested'?'collected':'received'}. This does not create a test result.</p>`+field('actualAt','Actual specimen event time',localInput(new Date().toISOString()),'datetime-local'),v=>perform({action:'test_status',testId:id,status:t.status==='requested'?'collected':'received',actualAt:new Date(v.actualAt).toISOString(),note:v.note}))},assignTest(id){dialog('Assign result follow-up responsibility',field('ownerLabel','Responsible clinician label'),v=>perform({action:'assign_test',testId:id,ownerLabel:v.ownerLabel,note:v.note}))},resultReview(id,decision){const report=episode().tests.find(t=>t.id===id).latest;dialog(decision?'Culture-to-treatment decision':'Acknowledge current report',decision?choice('decision','Decision',['retain','revise','escalate','defer']):'',v=>perform({action:decision?'culture_decision':'ack_result',testId:id,reportId:report.id,decision:v.decision,note:v.note}))},protocolRecord(id){protocolId=id;render()},editProtocol(){const p=localProtocols().versions.at(-1)||FNDynamic.defaultProtocol;dialog('Local hospital protocol · new version',field('name','Protocol name',p.name)+field('hospital','Hospital',p.hospital)+field('ward','Scope / ward',p.ward)+field('antibioticMinutes','Initial antibiotic target (10–60 min)',p.antibioticMinutes,'number')+field('reviewMinutes','Changed-data review target (1–120 min)',p.reviewMinutes,'number')+field('escalationTeam','Escalation team',p.escalationTeam)+field('allowedDrugs','Formulary codes (comma separated)',p.allowedDrugs.join(', '))+field('references','Evidence / protocol reference',p.references)+field('notes','Local protocol notes',p.notes),async v=>{try{const protocol={...v,antibioticMinutes:Number(v.antibioticMinutes),reviewMinutes:Number(v.reviewMinutes),allowedDrugs:v.allowedDrugs.split(',').map(s=>s.trim())};if(shared){const record=shared.data.protocols.find(p=>p.id===protocolId);if(record)await teamRequest('protocol','POST',{id:record.id,revision:record.revision,operation:{action:'edit',protocol,operationKey:teamRequestId(),note:v.note}});else{const res=await teamRequest('protocol-create','POST',{requestKey:teamRequestId(),protocol});protocolId=res.id}await refreshShared()}else{state.dynamicProtocols=FNDynamic.protocolEdit(state.dynamicProtocols,protocol,actor(),Date.now());persist()}closeDialog();render()}catch(e){document.querySelector('#dyn-form-error').textContent=e.message}})},approveProtocol(version,asRole){dialog('Review local protocol as '+asRole,'',async v=>{try{if(shared){const record=shared.data.protocols.find(p=>p.id===protocolId);await teamRequest('protocol','POST',{id:record.id,revision:record.revision,operation:{action:'approve',version,asRole,note:v.note,operationKey:teamRequestId()}});await refreshShared()}else{state.dynamicProtocols=FNDynamic.protocolApprove(state.dynamicProtocols,version,asRole,actor(),Date.now(),v.note);persist()}closeDialog();render()}catch(e){document.querySelector('#dyn-form-error').textContent=e.message}})},applyProtocol(version){dialog('Apply reviewed local protocol','<p>This creates a new input/plan revision; previous accepted plan remains visible and new approval is required.</p>',v=>perform({action:'apply_protocol',protocol:localProtocols().versions.find(p=>p.version===version),protocolId,version,note:v.note}))},runValidation(){try{validation=FNDynamicValidation.cohort(examples);render()}catch(e){error=e.message;render()}},export(){if(episode())download('FN_dynamic_'+episode().patientId+'.json',{syntheticOnly:true,source:shared?'shared_staff_workflow':'local_self_attested',episode:episode()})},exportMetrics(){const data=shared?shared.data.visits.map(v=>v.snapshot.dynamic).filter(Boolean):Object.values(state.dynamicEpisodes);download('FN_recorded_training_use_metrics.json',{syntheticOnly:true,measurement:FNDynamic.metrics(data.filter(d=>d.alerts.length||d.events.some(e=>!e.baseline&&e.by!=='LOCAL-RESULT-ADAPTER')),'recorded'),records:data,clinicalOutcomesProven:false})},exportValidation(){if(validation)download('FN_10_case_scripted_validation.json',validation)}};
function scanResults(pid){if(shared)return;const d=state.dynamicEpisodes[pid];if(!d)return;let next=d;const map={ANC:'anc',CrCl:'crcl',temperature:'temp',systolicBP:'sbp',heartRate:'hr',SpO2:'spo2'};for(const r of latestResults(pid)){const key='result-'+r.eventId;if(next.seen.includes(key)||seenResults.has(key))continue;if(!r.issuedAt||!r.observedAt||Date.parse(r.issuedAt)>Date.now())continue;seenResults.add(key);const patch={};if(map[r.code]&&typeof r.value==='number')patch[map[r.code]]=r.value;try{next=FNDynamic.mutate(next,{action:'observe',operationKey:key,note:'Received patient-matched result; no completed care inferred',event:{patch,baseline:r._actionRegistry&&r.availableAtMinutes===0,observedAt:r.observedAt,availableAt:r.issuedAt,source:r.source||'Synthetic imported result',result:{testId:r.accession,accession:r.accession,code:r.code,status:r.status,value:r.value,unit:r.unit,organism:r.organism,ast:Object.fromEntries((r.susceptibilities||[]).map(x=>[x.agent,x.interpretation])),text:r.reportText||''}}},{id:'LOCAL-RESULT-ADAPTER',role:'nurse'},Date.now())}catch(e){error='Result '+r.eventId+' was not applied: '+e.message}}if(next!==d){state.dynamicEpisodes[pid]=next;updateRegistry(next);persist()}}
let scanning=false;const beforeRender=render;render=function(){if(!shared&&!scanning&&storeReady){scanning=true;try{let added=false;for(const p of patients)if(!state.dynamicEpisodes[id(p)]){initializeLocal(id(p),false);added=true}if(added)persist();for(const pid of Object.keys(state.dynamicEpisodes))scanResults(pid)}finally{scanning=false}}beforeRender();if(view==='Dynamic reassessment')$('#app').innerHTML=renderPage()};
const beforeNav=renderNavigation;renderNavigation=function(){const h=beforeNav();return h.replace(/(<button[^>]+onclick="(?:fnIntake.open\(\)|go\('Patient assessment'\))"[\s\S]*?<\/button>)/,`$1<button onclick="go('Dynamic reassessment')" class="${view==='Dynamic reassessment'?'active':''}">${uiIcon('heart')}<span>Dynamic reassessment</span></button>`)};
const originalOverview=overview;overview=function(){return originalOverview().replace('＋ New assessment</button>',`＋ New assessment</button><button class="btn" onclick="go('Dynamic reassessment')">Dynamic follow-up</button>`)};
const previousDetail=detail;detail=function(){const h=previousDetail();return selected?`<div class="banner"><b>Patient-linked dynamic follow-up</b> <button class="btn" onclick="fnDyn.open('${id(selected)}')">Open dynamic reassessment</button></div>`+h:h};
const beforeRegister=fnA2A.registerEntered;fnA2A.registerEntered=function(c){const old=state.dynamicEpisodes[c.patientId];const value=beforeRegister(c);if(!old){state.dynamicEpisodes[value.patientId]=FNDynamic.initialize({patientId:value.patientId,label:value.displayName,input:value.input,triageAt:value.intakeContext?.triageAt||value.simulationStartedAt,triageKnown:!!value.intakeContext?.triageAt,protocol:activeProtocol(),mode:'recorded'},Date.now());persist()}if(old&&JSON.stringify(old.input)!==JSON.stringify(c.input)){try{state.dynamicEpisodes[c.patientId]=FNDynamic.mutate(old,{action:'observe',operationKey:teamRequestId(),note:'Entered assessment revised; old plan retained pending reapproval',event:{patch:c.input,observedAt:new Date().toISOString(),availableAt:new Date().toISOString(),source:'Edited New Assessment'}},{id:'LOCAL-ASSESSMENT-OPERATOR',role:'nurse'},Date.now());persist()}catch(e){error=e.message}}return value};
const previousReview=reviewResult;reviewResult=function(eid){previousReview(eid);const r=state.results.find(r=>r.eventId===eid);if(r&&state.dynamicEpisodes[r.patientId])scanResults(r.patientId)};
setInterval(()=>{if(document.hidden)return;if(view==='Dynamic reassessment'){if(shared){if(!document.querySelector('#workflowDialog'))refreshShared().then(()=>render()).catch(e=>{error=e.message})}else{if(patientId)scanResults(patientId);if(!document.querySelector('#workflowDialog'))render()}}},10000);
const oldGo=go;go=function(v){if(v==='Dynamic reassessment')history.replaceState(null,'','#dynamic');else if(location.hash==='#dynamic')history.replaceState(null,'',location.pathname+location.search);return oldGo(v)};if(location.hash==='#dynamic')view='Dynamic reassessment';
async function load(){try{const [es,report]=await Promise.all([fetch('dynamic-examples.json').then(r=>r.json()),fetch('dynamic-validation.json').then(r=>r.json())]);examples=es;validation=report;for(const e of examples)if(!state.customActionCases.some(c=>c.id===e.enteredId))fnA2A.registerEntered(FNIntakeCore.makeCase(e.enteredId,e.input,{alias:e.name,history:e.history,triageAt:e.anchor}));persist();render()}catch(e){error='Dynamic examples unavailable: '+e.message;if(view==='Dynamic reassessment')render()}}load();openStore();
})();
